catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    g_form.clearOptions('certificate_group');
	g_form.setMandatory('certificate_group',true);
    var policy = g_form.getValue("certificate_policy");
    var ca_tag_name = g_form.getValue("ca_tag_name");
    var company_name = g_form.getValue('company_name');
    var ajax = new GlideAjax('get_certificate_groups');
    ajax.addParam('sysparm_name', 'checkgroups');
    ajax.addParam("sysparm_policy", policy);
    ajax.addParam("sysparm_ca_tag_name", ca_tag_name);
    ajax.addParam("sysparm_company", company_name);
    ajax.addParam('sysparm_existing', newValue);
    ajax.getXML(serverdata);

    function serverdata(response) {
        try {
            var res = response.responseXML.documentElement.getAttribute('answer');
            try {
                res = JSON.parse(res);
                if (res.response.output.status != "Success") {
                    var msg = res.response.output.message;
                    throw JSON.stringify(msg);

                } else {
                    var groups = res.response.output.certificate_group;
                    g_form.addOption('certificate_group', "", "Select");
                    for (var iterator = 0; iterator < groups.length; iterator++) {
                        g_form.addOption('certificate_group', groups[iterator], groups[iterator]);
                    }

                }

            } catch (err) {
                throw JSON.stringify(res);

            }
        } catch (error) {
            alert(error);
            g_form.clearValue('certificate_group');
        }
    }
}
